// GENERATED by the marker generator (map pins as bitmaps). Do not edit by hand.
// Bitmap markers are drawn by Google Maps itself, so they can never be cropped by the
// react-native-maps 1.20.1 custom-view snapshot bug (fixed 100x100px bitmap on New Arch).
export type PinKind = "pickup" | "drop";
export type PinState = "normal" | "focused" | "late";

const PINS: Record<string, number> = {
  "pickup-normal": require("../../assets/markers/pickup-normal.png"),
  "pickup-normal-2": require("../../assets/markers/pickup-normal-2.png"),
  "pickup-normal-3": require("../../assets/markers/pickup-normal-3.png"),
  "pickup-normal-4": require("../../assets/markers/pickup-normal-4.png"),
  "pickup-normal-5": require("../../assets/markers/pickup-normal-5.png"),
  "pickup-focused": require("../../assets/markers/pickup-focused.png"),
  "pickup-focused-2": require("../../assets/markers/pickup-focused-2.png"),
  "pickup-focused-3": require("../../assets/markers/pickup-focused-3.png"),
  "pickup-focused-4": require("../../assets/markers/pickup-focused-4.png"),
  "pickup-focused-5": require("../../assets/markers/pickup-focused-5.png"),
  "pickup-late": require("../../assets/markers/pickup-late.png"),
  "pickup-late-2": require("../../assets/markers/pickup-late-2.png"),
  "pickup-late-3": require("../../assets/markers/pickup-late-3.png"),
  "pickup-late-4": require("../../assets/markers/pickup-late-4.png"),
  "pickup-late-5": require("../../assets/markers/pickup-late-5.png"),
  "drop-normal": require("../../assets/markers/drop-normal.png"),
  "drop-focused": require("../../assets/markers/drop-focused.png"),
  "drop-late": require("../../assets/markers/drop-late.png"),
};

/** Pin bitmap for a stop. Restaurants with several orders get a count badge (2–4, 5+). */
export function pinImage(kind: PinKind, state: PinState, count?: number | null): number {
  const n = kind === "pickup" && count && count > 1 ? Math.min(count, 5) : 0;
  return PINS[`${kind}-${state}${n ? `-${n}` : ""}`] ?? PINS[`${kind}-${state}`];
}

/** The pin's ground dot sits at this fraction of the image height (Marker anchor y). */
export const PIN_ANCHOR_Y = 0.8182;

export const HEADING_ARROW: number = require("../../assets/markers/heading-arrow.png");
